import sys

MOD = 998244353

def dp(s):
    n = len(s)
    if n == 0:
        return []
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][1] = 1
    for i in range(n):
        for j in range(i + 1, n + 1):
            if s[i] != s[j - 1]:
                dp[i + 1][j] = (dp[i + 1][j] + dp[i][j]) % MOD
                dp[i][j - 1] = (dp[i][j - 1] + dp[i][j]) % MOD
    return [sum(dp[i]) for i in range(n + 1)]

def main():
    import sys
    import itertools
    input = sys.stdin.read().split()
    x, y = input[0], input[1]
    nx, ny = len(x), len(y)
    res = 0
    for l1, r1 in itertools.combinations(range(nx + 1), 2):
        for l2, r2 in itertools.combinations(range(ny + 1), 2):
            dx = dp(x[l1:r1])
            dy = dp(y[l2:r2])
            for i in range(len(dx)):
                res = (res + dx[i] * dy[len(dy) - i - 1]) % MOD
    print(res)

main()
